import type { ManagementDecision } from './expanded-management';

// Source declarations consumed by source-assessment.ts, not a standalone runtime evaluator.
export type ClinicalFormula = {
  readonly operator: 'RATIO_PERCENT';
  readonly numerator: string;
  readonly denominator: string;
  readonly input: 'INTEGER' | 'DENOMINATOR_CONTEXT' | 'ESTIMATED';
  readonly numeratorSubset: boolean | 'CONTEXT_REQUIRED';
  readonly denominatorBasis: 'REGISTER' | 'SASARAN' | 'ESTIMATE' | 'VISITS';
  readonly documentedFactor?: number;
} | { readonly operator: 'COUNT'; readonly numerator: string };

export type ClinicalDecision = Omit<ManagementDecision, 'definitionId' | 'kind' | 'formula' | 'period' | 'target' | 'applicability'> & {
  readonly definitionId: `DO26-K${2 | 3}-R${number}`;
  readonly kind: 'RATIO' | 'COHORT' | 'ESTIMATED_RATIO' | 'LAST_VISIT' | 'VERIFIED_ZERO_RATIO' | 'MIXED_GRAIN_RATIO' | 'COUNT' | 'UNDEFINED';
  readonly formula: ClinicalFormula | null;
  readonly period: 'ANNUAL' | 'PROGRAM_YEAR' | 'SCHOOL_YEAR' | 'COHORT_WINDOW' | 'EXPLICIT_WINDOW' | 'AS_OF';
  readonly target: Omit<ManagementDecision['target'], 'excelNumberFormat'> & { readonly excelNumberFormat: '0%' | '0.0%' };
  readonly calculability: 'RATIO_WITH_CONTEXT' | 'COUNT_ONLY' | 'UNDEFINED' | 'SOURCE_BLOCKED';
  // Exact substring of F, not the review/formulaFamily annotation. E and G remain authoritative too.
  readonly calculationQuote: string;
  readonly zeroException?: { readonly kind: 'DINSOS_VERIFIED_NIHIL'; readonly measurement: null; readonly targetMet: true; readonly numericScore: null };
};

